import{c as t,ah as e,L as d,O as r}from"./chunks/framework.YKVbmyBD.js";const b=JSON.parse('{"title":"社区介绍","description":"","frontmatter":{},"headers":[],"relativePath":"acovia-server/1-1.md","filePath":"acovia-server/1-1.md"}'),i={name:"acovia-server/1-1.md"};function l(h,a,p,s,n,o){return e(),d("div",null,[...a[0]||(a[0]=[r('<h1 id="社区介绍" tabindex="-1">社区介绍 <a class="header-anchor" href="#社区介绍" aria-label="Permalink to “社区介绍”">​</a></h1><h2 id="服务器信息" tabindex="-1">服务器信息 <a class="header-anchor" href="#服务器信息" aria-label="Permalink to “服务器信息”">​</a></h2><p>版本：1.21.9 - 26.1.2</p><p>推荐使用 26.1.2</p><ul><li><p>Acovia 服务器本身为 26.1.2 版本，但向下兼容至 1.21.9 即更低版本的客户端也可以进入游戏游玩！</p></li><li><p>Acovia 服务器启用正版验证。</p></li></ul><h2 id="一些特殊玩法" tabindex="-1">一些特殊玩法 <a class="header-anchor" href="#一些特殊玩法" aria-label="Permalink to “一些特殊玩法”">​</a></h2><p>柏茯灵使用数据包为服务器编写了一些特殊玩法，如下：</p><h3 id="资源开采处-资源维度" tabindex="-1">资源开采处：资源维度 <a class="header-anchor" href="#资源开采处-资源维度" aria-label="Permalink to “资源开采处：资源维度”">​</a></h3><p>为了服务器的长久发展，柏茯灵不提倡在主世界获取一些不可再生资源，因为这会严重破坏服务器的地形，久而久之服务器的地形会变得支离破碎，所以柏茯灵在内层服务器设立了资源维度来供玩家随意开采。</p><p>进入方式如下：</p><p>在小镇中心找到一个海晶石材质的喷泉，随后底座有一张告示牌，下方是一个命令方块，右键告示牌即可前往资源维度，资源维度同理，可以回到现代。</p><p>如果告示牌不在，可以激活命令方块重新生成。</p><h3 id="再生之花" tabindex="-1">再生之花 <a class="header-anchor" href="#再生之花" aria-label="Permalink to “再生之花”">​</a></h3><p>手持再生之花的玩家受到致命伤害时，会立刻被拉回到安全区域，作为死亡不掉落的替代方案。</p><p>合成方法如下：</p><table tabindex="0"><thead><tr><th></th><th></th><th></th></tr></thead><tbody><tr><td>花</td><td>末影珍珠</td><td>花</td></tr><tr><td>末影珍珠</td><td>钻石</td><td>末影珍珠</td></tr><tr><td>花</td><td>末影珍珠</td><td>花</td></tr></tbody></table><h3 id="回溯卷轴" tabindex="-1">回溯卷轴 <a class="header-anchor" href="#回溯卷轴" aria-label="Permalink to “回溯卷轴”">​</a></h3><p>右键使用此卷轴，可以回到主城。</p><p>合成方法如下：</p><table tabindex="0"><thead><tr><th></th><th></th><th></th></tr></thead><tbody><tr><td>纸</td><td>末影珍珠</td><td>纸</td></tr><tr><td>末影珍珠</td><td>纸</td><td>末影珍珠</td></tr><tr><td>纸</td><td>末影珍珠</td><td>纸</td></tr></tbody></table><h2 id="加入服务器" tabindex="-1">加入服务器 <a class="header-anchor" href="#加入服务器" aria-label="Permalink to “加入服务器”">​</a></h2><p>你需要安装一个 1.21.9 及其以上的任意版本来进入服务器，同时不限制模组加载器。</p><p>你需要一个 Java 版的正版账号。</p><p>地址：</p><div class="language-txt"><button title="Copy Code" class="copy"></button><span class="lang">txt</span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>acovia.net</span></span></code></pre></div><h2 id="服务器规则" tabindex="-1">服务器规则 <a class="header-anchor" href="#服务器规则" aria-label="Permalink to “服务器规则”">​</a></h2><p>服务器内规则条款：</p><ul><li><p>禁止在主世界挖掘资源、破坏地形、破坏建筑，服务器有设立独立的资源维度，采集资源请前往资源维度，请查看 <a href="#资源开采处资源维度">资源开采处：资源维度</a></p></li><li><p>小型生电机器请在资源维度制造，若生电机器有建造地狱门需求，可以在主世界 (1024, 1024) ~ (1536, 1536) 处建造。</p></li><li><p>允许在本服务器内宣传其他服务器，但禁止吹捧，拉踩。</p></li><li><p>加入本服务器即表示您已阅读并同意条款并遵守服务器规则。</p></li></ul><hr><div align="center"> --- 由 柏茯灵_RsDline/REoxygen 编写 --- </div>',30)])])}const _=t(i,[["render",l]]);export{b as __pageData,_ as default};
